import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"艮下兌上 鹹：","description":"京氏易傳 - 艮下兌上 鹹：","frontmatter":{"title":"艮下兌上 鹹：","description":"京氏易傳 - 艮下兌上 鹹："},"headers":[],"relativePath":"classics/jingshi/061.md","filePath":"classics/jingshi/061.md"}'),r={name:"classics/jingshi/061.md"};function l(c,a,o,d,p,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"艮下兌上-鹹",tabindex:"-1"},[i("艮下兌上 鹹： "),e("a",{class:"header-anchor",href:"#艮下兌上-鹹","aria-label":"Permalink to “艮下兌上 鹹：”"},"​")],-1),e("p",null,"山下有澤，（虎易注：下字當為上字之誤。《鹹》象曰：山上有澤，鹹；君子以虛受人。）虛已畜物，陽中積陰，感於物也。陽下於陰，男女之道，內外相應，感類於象也。六二待聘，九五見召，二氣交感，夫婦之道，體斯合也。《易》曰：“鹹，感也，利取吉女。”（虎易注：此處錯句。《鹹》彖曰：鹹，感也。柔上而剛下，二氣感應以相與，止而說，男下女，是以亨利貞，取女吉也。）【艮少男，兌少女，男下於女，取婦之象。】與艮為飛伏。【丙申金，丁丑土。】九三三宮居世，上六宗廟為應。",-1),e("p",null,"建始戊午之癸亥，【芒種，小雪。】積算起癸亥至壬戌，週而復始。火土入艮兌。【分火土象入艮兌也。】",-1),e("p",null,"五星從位起熒惑，【火星南方入金宮。】柳宿從位降丙申，【二十八宿，分柳宿入鹹九三丙申金爻上。】分氣候三十六。【積算起數，分三十六位起吉凶。】",-1),e("p",null,"土上見金，母子氣和，陰陽相應，剛柔定位。吉凶隨爻，受氣出則吉，刑則兇。陰陽等降入外險，止於內象，為山水蹇卦。（虎易注：當為水山蹇卦之誤。）【九四爻之入陰中剛。】",-1)])])}const h=s(r,[["render",l]]);export{f as __pageData,h as default};
